from pathlib import Path
from datetime import datetime,timezone,timedelta
import json,ast,hashlib,xml.etree.ElementTree as ET
ROOT=Path(__file__).resolve().parents[4];OUT=Path(__file__).resolve().parent
sources=['src/content_factory/creative_workflow.py','src/content_factory/creative_stage_debug.py','src/content_factory/media_review_policy.py','src/scheduler/queue.py']
source_checks=[]
for name in sources:
 p=ROOT/name;ast.parse(p.read_text(encoding='utf-8-sig'))
 source_checks.append({'path':name,'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'syntax_valid':True})
def stats(name):
 suites=list(ET.parse(OUT/(name+'_tests.xml')).getroot().iter('testsuite'))
 totals={k:sum(int(s.get(k,0)) for s in suites) for k in ['tests','failures','errors','skipped']}
 totals['passed']=totals['tests']-totals['failures']-totals['errors']-totals['skipped']
 return totals
probes=json.loads((OUT/'boundary_results.json').read_text(encoding='utf-8'))
summary={'schema':'p1_independent_recheck/v1','created_at_bjt':datetime.now(timezone(timedelta(hours=8))).isoformat(),'verdict':'two_remaining_blockers','core_tests':stats('core'),'worker_boundary_tests':stats('worker'),'diff_check':json.loads((OUT/'diff_check.json').read_text(encoding='utf-8-sig')),'p1_scoped_diff_check':json.loads((OUT/'p1_diff_check.json').read_text(encoding='utf-8-sig')),'source_checks':source_checks,'verified_improvements':{'must_fix_prevents_downstream_model_call':probes['downstream_feedback_gate']['downstream_blocked'],'changed_candidate_invalidates_approval':probes['media_identity']['changed_candidate_rejected'],'late_result_cannot_overwrite_recovered_task':probes['worker_late_result']['late_result_fenced'],'actual_worker_heartbeat_renews_active_lease':True},'remaining_findings':[{'id':'R01','priority':'P1','title':'普通恢复无法到达非首阶段的返修目标','file':'src/content_factory/creative_workflow.py','line':5885,'evidence':probes['responsible_stage_resume'],'fix_direction':'允许读取仍有效且输入一致的缓存上游，或增加显式责任阶段返修入口；到达目标后才调用模型，目标修订及复核完成前阻止下游。'},{'id':'R02','priority':'P1','title':'当前治理包仍绑定修复前的运行时源码','file':'src/content_factory/creative_governed_runtime.py','line':7,'evidence':probes['governance_binding'],'fix_direction':'发布绑定修复后源码的新冻结治理包，保留旧包并明确现有任务的版本迁移策略；复核完整性与真实治理入口。'}],'limitations':['This recheck excludes the known Streamlit UI startup-timeout cases','No paid calls, real media review or publishing','New Worker tests are saved under QA artifacts and are not yet part of the default tests directory'],'business_code_modified':False,'historical_receipts_overwritten':False}
(OUT/'recheck_summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>P1 修复独立复核</title><style>body{font:16px/1.8 "Microsoft YaHei",system-ui,sans-serif;background:#f5f7fa;color:#1b2c3d;margin:0}main{max-width:960px;margin:30px auto;padding:28px;background:white;border:1px solid #d6dfea;border-radius:12px}h1{font-size:26px}h2{font-size:20px}a{color:#1757a8}li{margin:9px 0}.note{font-size:14px;color:#586878}.callout{padding:15px;background:#fff3e7;border-left:4px solid #bb711c}code{padding:2px 4px;background:#f0f3f8}@media(max-width:650px){main{margin:12px;padding:18px}}</style><main><p class="note">2026 年 10 月 2 日 · 原核验报告与业务源码保持不变</p><h1>核心回归通过，仍有两处阻断需要处理</h1><p>独立复跑相关六个模块：<strong>290 passed</strong>。补跑 Worker 精确边界专测：<strong>2 passed</strong>，分别覆盖执行期间被回收后返回迟到结果，以及超过初始租约后仍靠心跳完成任务。四个 P1 源文件语法检查与 P1 文件范围的 git diff --check 通过。全工作区检查返回 2，另外两个文件存在末尾新增空行：src/shared/llm_providers/base.py 第 156 行、tests/test_script_llm_response.py 第 70 行；没有在本轮修改这些文件。</p><ul><li>未解决的 must_fix 已能阻止下游模型调用。</li><li>候选视频、任务身份变化后，旧批准校验会拒绝续段。</li><li>被回收的任务保持 outcome_unknown，迟到成功结果没有覆盖状态或写入结果；正常长任务的 Worker 会实际续租。</li></ul><div class="callout">上述保护逻辑已验证，但“阻止下游”与“能够返修并恢复”是两个验收条件。当前普通恢复路径尚不能到达非首阶段的返修目标，显式治理流程也被旧源码哈希绑定阻断，因此仍不能确认整体完成。</div><h2>1 非首阶段的返修路径被上游缓存挡住</h2><p>在 director_brief 完成后登记 must_fix，按同一任务普通恢复或单步运行，流程首先经过已缓存的 writer_analysis；<a href="../../../../src/content_factory/creative_workflow.py">第 5885 行附近门控</a>因为当前阶段不是 director_brief 立即抛错。结果为 needs_attention，新模型调用 0 次，无法到达应修订的 director_brief。</p><p>建议允许读取未失效、输入一致的上游缓存，或提供明确的责任阶段返修入口；在责任阶段完成修订和复核之前，继续阻止真正的下游模型调用。新增用例应覆盖给导演或剧本等非首阶段反馈后，仍能从原任务修订并恢复。</p><h2>2 v18 绑定的源码哈希尚未更新为本次修复版本</h2><p>当前运行时仍选择 <a href="../../../creative_governance/20261002_v18_platform_refactor/runtime_sources.json">v18 包</a>，其中 creative_workflow.py 和 creative_stage_debug.py 的冻结哈希与修复后的文件不一致。通过正式 bind_registry / validate_registry_binding 校验，实际抛出 <code>RUNTIME_SOURCE_CHANGED: src/content_factory/creative_workflow.py</code>。影响的是显式 governed_production_v1 路径，不代表所有 legacy 流程都失败。</p><p>建议发布绑定本次修复源码的新冻结治理包，保留旧包，明确旧任务继续或迁移的规则，并复核真实治理入口；不能将旧版本的成功回执当成本次源码的验证。</p><h2>可复核的文件</h2><ul><li><a href="core_tests.xml">290 项核心 JUnit</a>与<a href="core_selection.json">模块范围</a></li><li><a href="worker_tests.xml">Worker 两项专测 JUnit</a>与<a href="test_worker_boundaries.py">测试源码</a></li><li><a href="boundary_results.json">五项边界复现结果</a>与<a href="recheck_boundaries.py">复运行脚本</a></li><li><a href="recheck_summary.json">完整机器可读核验结果</a></li></ul><p class="note">Worker 专测目前保存在 QA 目录，尚未加入默认 tests 目录。此次未复跑已知超时的 UI 测试，未修改业务源码，未发起付费调用、审查真实媒体或发布作品。原有完整交付质量的限制仍保留。</p></main></html>'''
(OUT/'recheck_report.html').write_text(html,encoding='utf-8')
print(json.dumps({'verdict':summary['verdict'],'core_tests':summary['core_tests'],'worker_tests':summary['worker_boundary_tests'],'syntax_checks':len(source_checks),'diff_check':summary['diff_check']},ensure_ascii=False))
